const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Boston, MA coordinates
  const boston = ee.Geometry.Point([-71.06, 42.36]);

  // Date range: January 29 - February 5, 2019
  const startDate = '2019-01-29';
  const endDate = '2019-02-05';

  // Load ERA5-Land daily temperature data
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
    .filterDate(startDate, endDate)
    .select('temperature_2m_max'); // Daily max temperature at 2m in Kelvin

  // Check if collection has data
  const colSize = era5.size().getInfo();
  console.log(`ERA5-Land images in period: ${colSize}`);

  if (colSize === 0) {
    console.log('No ERA5-Land data found for date range.');
    console.log('C1');
    return;
  }

  // Extract temperature values at Boston location for each day
  const tempCollection = era5.map(function(img) {
    const temp = img.sample(boston, 11132).first().get('temperature_2m_max');
    return ee.Feature(null, {'temp_k': temp, 'date': img.get('system:index')});
  });

  // Get all temperature values
  const temps = tempCollection.aggregate_array('temp_k').getInfo();
  console.log(`Temperatures retrieved: ${temps.length}`);

  if (temps.length === 0) {
    console.log('No valid temperature samples extracted.');
    console.log('C2');
    return;
  }

  // Convert from Kelvin to Celsius and filter out nulls
  const tempsCelsius = temps
    .filter(t => t !== null)
    .map(t => t - 273.15);

  console.log(`Valid temp samples: ${tempsCelsius.length}`);

  if (tempsCelsius.length === 0) {
    console.log('No valid temperature values after filtering.');
    console.log('C2');
    return;
  }

  // Find max and min temperatures
  const maxTemp = Math.max(...tempsCelsius);
  const minTemp = Math.min(...tempsCelsius);
  const tempDiff = maxTemp - minTemp;

  // Validate results
  if (isNaN(maxTemp) || isNaN(minTemp) || isNaN(tempDiff)) {
    console.log('Temperature calculation resulted in NaN.');
    console.log('C3');
    return;
  }

  console.log(`Max temp: ${maxTemp.toFixed(2)}°C`);
  console.log(`Min temp: ${minTemp.toFixed(2)}°C`);
  console.log(`Difference: ${tempDiff.toFixed(2)}°C`);

  // Answer the question: Is there at least 30°C difference?
  if (tempDiff >= 30) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
